        }
        durationMs
      }
      ... on ClipReady {
        artifact {
          ... EventArtifactFields
        }
        durationMs
        sizeBytes
      }
      ... on ClipFailed {
        artifact {
          ... EventArtifactFields
        }
        mediaFailureReason: reason
      }
      ... on CustomDomainVerified {
        domain
      }
      ... on CustomDomainFailed {
        domain
        customDomainFailureReason: reason
      }
      ... on MultistreamStatusChanged {
        streamId
        targetId
        targetName
        status
        previousStatus
      }
      ... on RecordingReady {
        artifact {
          ... EventArtifactFields
        }
        durationMs
        sizeBytes
      }
      ... on RecordingFailed {
        artifact {
          ... EventArtifactFields
        }
        mediaFailureReason: reason
      }
      ... on StreamConnected {
        streamId
        protocol
      }
      ... on StreamCreated {
        streamId
        name
        playbackId
      }
      ... on StreamDeleted {
        streamId
      }
      ... on StreamIdle {
        streamId
      }
      ... on StreamKeyRotated {
        streamId
      }
      ... on StreamLive {
        streamId
      }
      ... on StreamUpdated {
        streamId
        changedFields
      }
      ... on UploadCreated {
        artifact {
          ... EventArtifactFields
        }
